import doctest, importlib, pkgutil, re, sys, warnings
sys.path.insert(0, '/workspace/task/source')
warnings.simplefilter('ignore')
import numpy as np
import specutils

NUM = re.compile(r'[-+]?(?:\d+\.\d*(?:[eE][-+]?\d+)?|\.\d+(?:[eE][-+]?\d+)?|\d+[eE][-+]?\d+)')

class FloatChecker(doctest.OutputChecker):
    def check_output(self, want, got, optionflags):
        if doctest.OutputChecker.check_output(self, want, got, optionflags):
            return True
        w = NUM.findall(want); g = NUM.findall(got)
        if len(w) != len(g) or not w:
            return False
        try:
            wa = np.array([float(x) for x in w]); ga = np.array([float(x) for x in g])
        except ValueError:
            return False
        # structure check: strip numbers and compare skeleton
        sw = NUM.sub('N', want); sg = NUM.sub('N', got)
        if ' '.join(sw.split()) != ' '.join(sg.split()):
            return False
        return np.allclose(wa, ga, rtol=1e-5, atol=1e-8, equal_nan=True)

runner_total = [0,0]
for mod in pkgutil.walk_packages(specutils.__path__, 'specutils.'):
    name = mod.name
    if '.io.' in name or name.endswith('conftest'):
        continue
    try:
        m = importlib.import_module(name)
    except Exception as e:
        print('SKIP', name, type(e).__name__, e)
        continue
    finder = doctest.DocTestFinder()
    runner = doctest.DocTestRunner(checker=FloatChecker(), optionflags=doctest.NORMALIZE_WHITESPACE|doctest.ELLIPSIS)
    for t in finder.find(m, name):
        if not t.examples: continue
        runner.run(t, out=lambda s: sys.stdout.write(s))
    r = runner.summarize(verbose=False)
    runner_total[0]+=r.failed; runner_total[1]+=r.attempted
print('FAILED', runner_total[0], 'of', runner_total[1])
EOF
